*{box-sizing:border-box} :root{--bg:#091110;--panel:#101a18;--panel2:#14201d;--stroke:#263632;--text:#e8eee8;--muted:#758681;--lime:#c8f36a;--amber:#e3b976;--red:#ff6f63;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}html,body{margin:0;width:100%;height:100%;background:var(--bg);color:var(--text);font-family:var(--sans);overflow:hidden}body{background-image:radial-gradient(ellipse at 42% -20%,#1b2b26 0%,transparent 55%),linear-gradient(130deg,#08100f,#0c1513 62%,#09100f)}button{font:inherit}.app-shell{height:100dvh;max-width:1600px;margin:auto;padding:0 4.1vw;display:flex;flex-direction:column}.topbar{height:72px;flex-shrink:0;display:flex;align-items:center;border-bottom:1px solid #25312e;position:relative}.brand{display:flex;gap:12px;align-items:center}.brand-mark{width:26px;height:26px;display:grid;grid-template-columns:1fr 1fr;gap:3px;transform:rotate(-8deg)}.brand-mark span{background:var(--lime);border-radius:1px}.brand-mark span:nth-child(2){opacity:.55}.brand-mark span:nth-child(3){opacity:.75}.brand-mark span:nth-child(4){opacity:.32}.brand b{font-size:13px;letter-spacing:2px;display:block;font-weight:800}.brand small{font:8px var(--mono);letter-spacing:1.55px;color:#87958f;display:block;margin-top:3px}.shift-status{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;font:9px var(--mono);letter-spacing:1px;color:#bbc5bd;white-space:nowrap}.shift-status i{height:13px;width:1px;background:#3c4843;margin:0 6px}.live-dot{height:7px;width:7px;border-radius:50%;background:#aef060;box-shadow:0 0 11px #a6ec59;display:inline-block;animation:pulse 1.8s infinite}.sound-toggle{margin-left:auto;background:none;border:1px solid #293733;color:#99a7a0;border-radius:3px;padding:8px 11px;font:9px var(--mono);letter-spacing:.7px;display:flex;gap:8px;align-items:center;cursor:pointer}.sound-toggle b{color:var(--lime);font-weight:500}.sound-icon{font-size:16px;color:var(--lime)}.main-layout{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 292px;gap:25px;padding:27px 0 21px}.monitor-column{min-width:0;display:flex;flex-direction:column}.monitor-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:16px}.eyebrow{font:9px var(--mono);color:#82918b;letter-spacing:1.15px}.heading-line{display:inline-block;width:25px;height:1px;background:#58675d;vertical-align:middle;margin:0 9px}.eyebrow b{color:#c3ccc4;font-weight:400}.monitor-heading h1{font-size:clamp(23px,2.4vw,34px);line-height:1.15;letter-spacing:-1.3px;margin:9px 0 0;font-weight:600}.title-period{color:var(--lime)}.time-chip{display:grid;grid-template-columns:8px auto;align-items:center;column-gap:7px;padding:7px 10px 6px;border:1px solid #2c3b35;border-radius:3px;font:11px var(--mono);color:#d8e0d9;margin-bottom:2px}.time-chip .clock-dot{width:6px;height:6px;border:1px solid var(--lime);border-radius:50%}.time-chip small{grid-column:2;font:7px var(--mono);color:#708078;letter-spacing:1px;margin-top:3px}.camera-grid{--gap:8px;position:relative;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:var(--gap);flex:1;min-height:260px;max-height:calc(100% - 104px);overflow:hidden}.feed{position:relative;background:#18231f;border:1px solid #34423a;overflow:hidden;min-height:0;transition:border-color .2s,box-shadow .2s}.feed:hover{border-color:#738866;box-shadow:0 0 0 1px #73886655}.feed.selected{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime),inset 0 0 35px #c8f36a16}.feed.caught{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime),inset 0 0 65px #c8f36a32}.feed.missed{animation:miss .45s}.feed-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.feed:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#07100f66 0%,transparent 26%,transparent 72%,#07100f55 100%);z-index:1}.feed-top,.feed-bottom{position:absolute;left:11px;right:11px;z-index:3;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.feed-top{top:9px}.feed-bottom{bottom:8px;font:8px var(--mono);letter-spacing:.7px;color:#aab8ad}.feed-bottom i{font-style:normal;color:var(--lime);margin:0 4px}.feed-time{color:#c1cabd}.cam-tag{font:9px var(--mono);letter-spacing:.7px;color:#e3e9dc;text-shadow:0 1px 5px #000}.cam-tag i{font-style:normal;color:var(--lime);margin-right:5px}.rec{font:8px var(--mono);letter-spacing:1px;color:#d4d7ca;text-shadow:0 1px 5px #000;display:flex;gap:5px;align-items:center}.rec b{width:5px;height:5px;border-radius:50%;background:#f36d5f;box-shadow:0 0 6px #f36d5f;animation:pulse 1s infinite}.feed-hit{position:absolute;inset:26px 0 22px;z-index:2;border:0;background:transparent;padding:0;cursor:crosshair;-webkit-tap-highlight-color:transparent}.scanlines{position:absolute;z-index:4;inset:0;pointer-events:none;opacity:.13;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,#0b1412 4px)}.feed-corner{position:absolute;z-index:3;top:3px;left:3px;width:13px;height:13px;border-top:1px solid #d5ef91aa;border-left:1px solid #d5ef91aa}.console-bar{border:1px solid #273832;background:#101917;height:38px;flex-shrink:0;margin-top:9px;display:flex;align-items:center;justify-content:space-between;padding:0 12px;color:#84938b;font:8px var(--mono);letter-spacing:.8px}.console-label{display:flex;align-items:center;gap:7px}.console-label b{color:#bdc9bc;font-weight:400}.console-led{width:5px;height:5px;border-radius:50%;background:var(--lime);box-shadow:0 0 7px #c8f36a}.console-sep{color:#45534a;margin:0 3px}.camera-switches{display:flex;gap:5px;align-items:center}.camera-switches span{margin-right:5px}.camera-switches b{font-weight:400;border:1px solid #35443b;padding:4px 6px;color:#acb9ae}.camera-switches b.active{background:#c8f36a;color:#101812;border-color:#c8f36a}.side-column{display:flex;flex-direction:column;gap:10px;min-height:0}.alert-card,.score-card,.activity-card{border:1px solid #273731;background:linear-gradient(145deg,#131e1b,#101917);border-radius:3px;padding:14px 15px}.alert-card{flex:0 0 40%;min-height:245px;position:relative;overflow:hidden}.card-head,.score-top,.activity-head{display:flex;justify-content:space-between;align-items:center}.case-index{font:8px var(--mono);color:#7b8982;letter-spacing:.7px}.case-index b{color:#bdc7ba;font-weight:400}.case-icon{position:absolute;top:51px;right:18px;width:75px;height:66px}.case-spark{color:#e5c27e;font-size:19px;position:absolute;top:0;left:3px}.case-ball{position:absolute;width:25px;height:25px;background:radial-gradient(circle at 30% 25%,#e8f38d,#b3da49 70%,#748c32);border-radius:50%;top:20px;right:15px;box-shadow:0 4px 10px #0009,inset -4px -4px 7px #566522;transform:rotate(-24deg)}.case-ball:after{content:'';position:absolute;width:16px;height:9px;border:1.3px solid #55652c;border-left-color:transparent;border-radius:50%;top:7px;left:4px;transform:rotate(-37deg)}.case-shadow{position:absolute;width:32px;height:7px;background:#080e0c88;border-radius:50%;right:12px;bottom:2px;filter:blur(2px)}.alert-card h2{font-size:22px;letter-spacing:-.8px;line-height:1.15;margin:36px 0 8px;font-weight:600;position:relative;z-index:1}.alert-card>p{font-size:10px;line-height:1.55;color:#93a099;margin:0;max-width:220px}.case-divider{height:1px;background:#293832;margin:13px 0 11px}.clue-label{display:flex;align-items:center;gap:9px}.clue-icon{font-size:22px;color:var(--lime);font-weight:300}.clue-label small{font:7px var(--mono);letter-spacing:.8px;color:#77867e;display:block;margin-bottom:4px}.clue-label b{font-size:10px;color:#d4e4c2;font-weight:600}.score-card{flex:0 0 20%;min-height:109px;padding:12px 15px}.streak{font:8px var(--mono);color:#9aa68f;letter-spacing:.4px}.score-number{font:29px var(--mono);letter-spacing:3px;color:var(--lime);margin:4px 0 5px;text-shadow:0 0 16px #b7ee6640}.score-meter{height:2px;background:#29372f;overflow:hidden}.score-meter span{display:block;width:0;height:100%;background:var(--lime);transition:width .5s}.score-footer{display:flex;align-items:center;gap:7px;margin-top:8px;font:7px var(--mono);color:#77867e;letter-spacing:.4px}.score-footer b{font-size:9px;color:#c5d0c4;font-weight:400}.score-footer i{height:9px;width:1px;background:#34443a;margin:0 5px}.activity-card{flex:1;min-height:105px;padding:12px 15px;overflow:hidden}.history-count{font:8px var(--mono);color:#74837b}.activity-list{margin-top:8px;display:flex;flex-direction:column;gap:5px;overflow:auto;max-height:calc(100% - 25px)}.empty-state{text-align:center;color:#728078;font-size:9px;line-height:1.5;padding:6px}.empty-state span{font-size:18px;color:#879b7a}.empty-state p{margin:2px}.sighting{display:grid;grid-template-columns:24px 1fr auto;align-items:center;gap:7px;padding:6px 7px;background:#17231f;border-left:2px solid #576d55;font-size:9px;color:#c8d1c8}.sighting.bad{border-left-color:#df8271}.sighting .s-icon{font-size:14px;text-align:center}.sighting small{display:block;color:#78877f;font:7px var(--mono);margin-top:2px}.sighting time{font:7px var(--mono);color:#829087}.tip-card{margin-top:auto;display:flex;align-items:center;gap:8px;padding:5px 3px;color:#89968f;font-size:9px;line-height:1.45}.tip-card p{margin:0}.tip-card b{color:#d8e1d6}.tip-star{font-size:19px;color:#c6a567}.footer{height:30px;flex-shrink:0;border-top:1px solid #24312c;display:flex;justify-content:space-between;align-items:center;color:#5d6b64;font:7px var(--mono);letter-spacing:1px}.footer b{color:var(--lime);font-size:8px}.toast{position:fixed;left:50%;bottom:52px;transform:translate(-50%,20px);padding:11px 18px;background:#17231e;border:1px solid #526248;color:#d9ebbf;font:10px var(--mono);letter-spacing:.5px;z-index:10;opacity:0;transition:opacity .2s,transform .2s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.toast.bad{border-color:#9c554b;color:#ffd2c5}.intro-overlay{position:fixed;inset:0;background:#050b0aee;z-index:20;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(8px);transition:opacity .35s,visibility .35s}.intro-overlay.hidden{opacity:0;visibility:hidden}.intro-card{width:min(390px,100%);border:1px solid #3b4a3e;background:linear-gradient(145deg,#17221e,#0f1715);padding:25px 31px 19px;position:relative;box-shadow:0 22px 90px #0009}.intro-kicker{font:9px var(--mono);letter-spacing:1.2px;color:#aebbaf;display:flex;align-items:center;gap:9px}.intro-illustration{height:110px;position:relative;margin:10px 0 0;background:radial-gradient(ellipse,#34463377,transparent 67%);display:flex;align-items:center;justify-content:center}.intro-cam{font-size:45px;color:#c8f36a;text-shadow:0 0 23px #c8f36a88}.intro-ball{position:absolute;width:24px;height:24px;border:2px solid #d4ef76;border-radius:50%;top:22px;right:88px;box-shadow:0 0 16px #d4ef7680}.intro-rays{position:absolute;left:90px;top:22px;color:#c8f36a;font-size:17px}.intro-card h2{font-size:31px;line-height:1.07;letter-spacing:-1.2px;margin:0 0 12px}.intro-card>p{font-size:11px;color:#9aa69e;line-height:1.6;margin:0 0 15px}.intro-instructions{display:grid;grid-template-columns:24px 1fr;align-items:center;gap:8px 9px;border-top:1px solid #2e3b34;border-bottom:1px solid #2e3b34;padding:12px 0;margin-bottom:14px}.intro-instructions span{font:9px var(--mono);color:var(--lime)}.intro-instructions p{margin:0;font-size:10px;color:#c3cec4}.start-button{width:100%;height:42px;border:0;background:var(--lime);color:#172019;font-size:10px;font-weight:800;letter-spacing:1px;cursor:pointer;text-align:left;padding:0 15px;display:flex;justify-content:space-between;align-items:center;transition:background .15s,transform .15s}.start-button:hover{background:#d7ff8b;transform:translateY(-1px)}.start-button span{font-size:18px}.intro-foot{text-align:center;font:7px var(--mono);letter-spacing:1px;color:#718078;margin-top:13px}
@keyframes pulse{50%{opacity:.42;box-shadow:0 0 2px currentColor}}@keyframes miss{25%{transform:translateX(-3px)}75%{transform:translateX(3px)}}
@media(max-width:850px){.app-shell{padding:0 20px}.main-layout{grid-template-columns:minmax(0,1fr) 255px;gap:15px}.alert-card{padding:12px}.alert-card h2{font-size:20px}.alert-card>p{font-size:9px}.score-footer{font-size:6px;gap:5px}}
@media(max-width:650px){html,body{overflow:auto;height:auto;min-height:100%}.app-shell{height:auto;min-height:100dvh;padding:0 13px}.topbar{height:57px}.brand-mark{width:21px;height:21px}.brand b{font-size:11px}.brand small{font-size:6px}.shift-status{position:static;transform:none;margin-left:auto;margin-right:8px;font-size:7px;gap:6px}.shift-status i,.shift-status #shift-clock{display:none}.sound-toggle{padding:6px 7px;font-size:7px;gap:4px}.sound-icon{font-size:13px}.main-layout{display:flex;flex-direction:column;gap:11px;padding:15px 0 12px}.monitor-heading{margin-bottom:10px}.monitor-heading h1{font-size:23px;margin-top:6px}.eyebrow{font-size:7px;letter-spacing:.8px}.heading-line{width:13px;margin:0 4px}.time-chip{padding:5px 7px;font-size:9px}.camera-grid{height:min(68vw,420px);min-height:250px;flex:none;gap:5px}.feed-top{top:6px;left:7px;right:7px}.feed-bottom{bottom:5px;left:7px;right:7px;font-size:6px}.cam-tag{font-size:7px}.rec{font-size:6px}.feed-hit{inset:22px 0 18px}.console-bar{height:32px;margin-top:6px;padding:0 7px;font-size:6px}.camera-switches{gap:3px}.camera-switches span{display:none}.camera-switches b{padding:3px 4px}.side-column{display:grid;grid-template-columns:1fr 1fr;gap:7px}.alert-card{grid-column:1/3;min-height:0;height:auto;padding:11px 12px}.alert-card h2{font-size:18px;margin:21px 0 5px}.alert-card>p{font-size:9px;max-width:70%}.case-icon{top:33px;right:13px;transform:scale(.8);transform-origin:top right}.case-divider{margin:8px 0}.clue-label small{font-size:6px}.clue-label b{font-size:9px}.score-card{min-height:93px;padding:10px}.score-top .eyebrow{font-size:6px}.score-number{font-size:25px;margin:2px 0}.score-footer{gap:4px;font-size:5px;margin-top:6px}.score-footer b{font-size:8px}.activity-card{min-height:93px;padding:10px;max-height:120px}.activity-head .eyebrow{font-size:6px}.activity-list{margin-top:4px}.empty-state{font-size:8px;padding:2px}.sighting{padding:4px;font-size:8px;grid-template-columns:18px 1fr auto}.sighting small,.sighting time{font-size:6px}.tip-card{grid-column:1/3;margin:0;padding:2px 4px;font-size:8px}.footer{height:26px;font-size:5px}.footer span:nth-child(2){display:none}.toast{bottom:15px;font-size:9px}.intro-card{padding:21px 23px 17px}.intro-card h2{font-size:29px}}
@media(min-width:651px) and (max-height:700px){.app-shell{padding-left:3vw;padding-right:3vw}.topbar{height:58px}.main-layout{padding:15px 0 12px;gap:18px;grid-template-columns:minmax(0,1fr) 270px}.monitor-heading{margin-bottom:10px}.alert-card{flex-basis:38%;min-height:205px;padding:11px 13px}.alert-card h2{margin-top:24px;font-size:20px}.alert-card>p{font-size:9px}.case-divider{margin:8px 0}.score-card{min-height:95px;padding:9px 13px}.score-number{font-size:25px;margin:1px 0 3px}.activity-card{min-height:90px;padding:9px 13px}.tip-card{font-size:8px}.footer{height:25px}}

import * as THREE from 'three';

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'low-power' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setClearColor(0x000000, 0);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
renderer.domElement.className = 'world-renderer';
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color('#101916');
scene.fog = new THREE.Fog('#101916', 24, 76);
scene.add(new THREE.HemisphereLight(0xc3d7c3, 0x25362d, 2.0));
const moon = new THREE.DirectionalLight(0xc2d6c3, 2.5);
moon.position.set(-14, 25, 16); scene.add(moon);
const warm = new THREE.PointLight(0xffcf83, 24, 19, 2); warm.position.set(13, 6, 0); scene.add(warm);
const mat = (color, roughness=.8, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const materials = {
  grass: mat('#344b3b'), darkGrass: mat('#253b30'), path: mat('#77796b'), concrete: mat('#77786d'),
  wall: mat('#9c9885'), cream: mat('#c3b89e'), brick: mat('#69594b'), wood: mat('#694f39'),
  darkWood: mat('#3c3b31'), metal: mat('#45534e', .55, {metalness:.45}), leaf: mat('#344d38'),
  leaf2: mat('#536845'), blue: mat('#557b86'), yellow: mat('#d1a950'), red: mat('#a95243'),
  white: mat('#ded8c4'), black: mat('#212925'), lime: mat('#c8ee62'), ball: mat('#c6e657',.4),
  window: new THREE.MeshStandardMaterial({color:'#394d50',roughness:.25,emissive:'#718b84',emissiveIntensity:.23}),
  dog: mat('#a87349'), dogLight: mat('#d4ad78'), human: mat('#587583'), kid: mat('#b57c54'),
  shadow: new THREE.MeshBasicMaterial({color:0x111912,transparent:true,opacity:.35,depthWrite:false})
};
const boxGeo = new THREE.BoxGeometry(1,1,1);
const sphereGeo = new THREE.SphereGeometry(1,14,10);
const cylGeo = new THREE.CylinderGeometry(.5,.5,1,10);
const capsuleGeo = new THREE.CapsuleGeometry(.22,.48,4,8);
function addMesh(parent, geometry, material, pos, scale, rotY=0) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...pos); mesh.scale.set(...scale); mesh.rotation.y=rotY;
  mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function box(parent, material, pos, scale, rot=0){return addMesh(parent,boxGeo,material,pos,scale,rot)}
function sphere(parent, material, pos, scale){return addMesh(parent,sphereGeo,material,pos,scale)}
function cylinder(parent, material, pos, scale, rot=0){return addMesh(parent,cylGeo,material,pos,scale,rot)}

const ZONES = [
  {name:'THE FRONT YARD', floor:'#344738', wall:'#9d987f', accent:'#c2a46e', kind:'yard'},
  {name:'MAPLE WALK', floor:'#555b4b', wall:'#787f6f', accent:'#d1b877', kind:'path'},
  {name:'SUNROOM', floor:'#5d5948', wall:'#a99b7c', accent:'#d7ad6b', kind:'patio'},
  {name:'LOADING BAY', floor:'#4a514b', wall:'#72796c', accent:'#c1a06e', kind:'bay'}
];
const centers = [-15,-5,5,15];
const cameras = [];
const feedEls = [...document.querySelectorAll('.feed')];
const props = [];

function tree(parent,x,z,size=1, autumn=false){
  cylinder(parent,materials.wood,[x,.52,z],[.19,1.05,.19]);
  const leaves = autumn ? materials.leaf2 : materials.leaf;
  sphere(parent,leaves,[x,.98,z],[.76*size,.88*size,.7*size]);
  sphere(parent,autumn?materials.yellow:materials.leaf2,[x-.3,.78,z+.09],[.43*size,.48*size,.43*size]);
  sphere(parent,leaves,[x+.32,1.24,z-.05],[.48*size,.55*size,.46*size]);
}
function lamp(parent,x,z){
  cylinder(parent,materials.metal,[x,1.45,z],[.08,2.9,.08]);
  box(parent,materials.metal,[x,2.86,z],[.54,.08,.14]);
  sphere(parent,mat('#f0d99d',.25,{emissive:'#edc77a',emissiveIntensity:1.6}),[x-.18,2.78,z],[.19,.12,.17]);
  const glow=new THREE.PointLight('#f0c77e',5,5,2);glow.position.set(x-.18,2.6,z);parent.add(glow);
}
function bench(parent,x,z){
  box(parent,materials.wood,[x,.58,z],[1.35,.13,.42]);
  box(parent,materials.wood,[x,.8,z-.17],[1.35,.5,.1]);
  for(const dx of [-.48,.48]) cylinder(parent,materials.metal,[x+dx,.31,z],[.08,.54,.08]);
}
function fence(parent,x,z,width=8){
  box(parent,materials.wood,[x,.7,z],[width,.12,.12]);
  box(parent,materials.wood,[x,.34,z],[width,.1,.1]);
  for(let i=0;i<width*1.1;i++){
    const px=x-width/2+.18+i*.8;
    if(px>x+width/2)break;
    box(parent,materials.wood,[px,.52,z],[.08,.65,.1]);
  }
}
function buildZone(index){
  const cx=centers[index], data=ZONES[index], root=new THREE.Group();root.position.x=cx;scene.add(root);
  const floor=mat(data.floor);box(root,floor,[0,-.22,0],[9,.4,7.4]);
  // enclosed rear boundary and a strong stripe of readable paving
  box(root,mat(data.wall),[0,1.25,-3.8],[9,3.2,.35]);
  box(root,materials.darkWood,[0,2.92,-3.58],[9,.18,.16]);
  for(let i=0;i<5;i++) box(root,materials.window,[-3.4+i*1.7,1.75,-3.59],[.95,1.05,.035]);
  box(root,materials.cream,[0,.08,-3.54],[9,.13,.12]);
  if(index===0){
    box(root,materials.path,[0,.005,.55],[2.25,.04,6.1]);
    for(let i=0;i<5;i++) box(root,materials.cream,[0,.035,2.8-i*1.12],[1.75,.05,.72]);
    tree(root,-3.35,.2,1.05);tree(root,3.25,-.6,.9,true);tree(root,-2.8,-2.2,.72,true);
    fence(root,0,3.45,8.2);bench(root,2.15,1.75);lamp(root,-1.7,-1.5);
    // mailbox and a small porch stoop
    box(root,materials.brick,[3.55,.65,-2.6],[.52,1.3,.42]);box(root,materials.metal,[3.55,1.28,-2.6],[.62,.12,.48]);
  } else if(index===1){
